import React from "react";

function About({ language }) {

  const content = {
    en: {
      title: "About Our Honey",
      text: `For more than 42 years, we have been dedicated to producing pure, natural, and high-quality honey.

Our journey began with a simple mission — to bring the true taste of nature directly to people’s homes.

Our honey is carefully collected from natural sources and processed with traditional knowledge passed down through generations.

We ensure that every drop of honey maintains its natural nutrients, aroma, and authentic flavor.

We believe honey is not just a sweetener but also a natural medicine and healthy lifestyle choice.

🍯 Pure Honey | Natural Taste | Trusted for 42 Years`
    },

    ta: {
      title: "எங்கள் தேன் பற்றி",
      text: `42 ஆண்டுகளுக்கும் மேலாக நாங்கள் தூய்மையான மற்றும் இயற்கையான தேனை தயாரித்து வழங்கி வருகிறோம்.

இயற்கையின் உண்மையான சுவையை மக்களின் வீடுகளுக்கு கொண்டு செல்ல வேண்டும் என்பதே எங்கள் நோக்கம்.

எங்கள் தேன் இயற்கை மலர்களிலிருந்து சேகரிக்கப்பட்டு பாரம்பரிய முறைகளில் தயாரிக்கப்படுகிறது.

ஒவ்வொரு துளியும் அதன் இயற்கை ஊட்டச்சத்துகள், மணம் மற்றும் உண்மையான சுவையை பாதுகாக்கும்.

தேன் என்பது இனிப்பு உணவாக மட்டுமல்ல, அது ஒரு இயற்கை மருந்தும் ஆகும்.

🍯 தூய தேன் | இயற்கை சுவை | 42 ஆண்டுகள் நம்பிக்கை`
    }
  };

  return (
    <div className="container py-5">
      <h1>{content[language].title}</h1>
      <p style={{ whiteSpace: "pre-line" }}>
        {content[language].text}
      </p>
    </div>
  );
}

export default About;
